trace.message:
@{
            try {
              var b = context.Request.Body.As(preserveContent: true);
              var o = new JObject();
              o["request_id"] = (string)context.Variables["reqId"];
              o["path"] = context.Request.Url.Path;
              var ua = context.Request.Headers.GetValueOrDefault("User-Agent", "");
              o["user_agent"] = ua.Length > 80 ? ua.Substring(0, 80) : ua;
              o["keys"] = string.Join(",", b.Properties().Select(p => p.Name));
              o["model"] = (string)b["model"];
              o["stream"] = b["stream"] == null ? "absent" : b["stream"].ToString();
              o["has_max_tokens"] = b["max_tokens"] != null;
              o["has_max_completion_tokens"] = b["max_completion_tokens"] != null;
              var msgs = b["messages"] as JArray;
              o["message_count"] = msgs == null ? 0 : msgs.Count;
              o["roles"] = msgs == null ? "" : string.Join(",", msgs.Select(m => (string)m["role"]));
              var tools = b["tools"] as JArray;
              o["tool_names"] = tools == null ? "" : string.Join(",", tools.Select(t => t["function"] != null ? (string)t["function"]["name"] : (string)t["type"]));
              var tc = b["tool_choice"] == null ? "absent" : b["tool_choice"].ToString(Newtonsoft.Json.Formatting.None);
              o["tool_choice"] = tc.Length > 100 ? tc.Substring(0, 100) : tc;
              return o.ToString(Newtonsoft.Json.Formatting.None);
            } catch (Exception) {
              return "request-shape-unavailable";
            }
          }
